package com.aetherteam.aether.perk.data;

import com.aetherteam.aether.perk.types.DeveloperGlow;
import com.aetherteam.aether.perk.types.Halo;
import com.aetherteam.aether.perk.types.MoaData;
import com.aetherteam.aether.perk.types.MoaSkins;
import com.google.common.collect.ImmutableMap;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.DimensionDataStorage;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

public class PerkSavedData extends SavedData {
    public static final String FILE_NAME = "perks";
    private final Map<UUID, MoaData> storedSkinData = new HashMap<>();
    private final Map<UUID, Halo> storedHaloData = new HashMap<>();
    private final Map<UUID, DeveloperGlow> storedDeveloperGlowData = new HashMap<>();

    /**
     * Saves perk data to the world in a file named "perks.dat".
     *
     * @param tag The {@link CompoundTag} to save the data to.
     * @return A {@link CompoundTag} with the data.
     */
    @Override
    public CompoundTag save(CompoundTag tag, HolderLookup.Provider lookupProvider) {
        CompoundTag storedSkinDataTag = new CompoundTag();
        for (Map.Entry<UUID, MoaData> moaDataEntry : this.storedSkinData.entrySet()) {
            CompoundTag moaDataEntryTag = new CompoundTag();
            if (moaDataEntry.getValue().moaUUID() != null) {
                moaDataEntryTag.putUUID("MoaUUID", moaDataEntry.getValue().moaUUID());
            }
            if (moaDataEntry.getValue().moaSkin() != null) {
                moaDataEntryTag.putString("MoaSkin", moaDataEntry.getValue().moaSkin().getId());
            }
            storedSkinDataTag.put(moaDataEntry.getKey().toString(), moaDataEntryTag);
        }
        tag.put("StoredSkinData", storedSkinDataTag);

        CompoundTag storedHaloDataTag = new CompoundTag();
        for (Map.Entry<UUID, Halo> haloEntry : this.storedHaloData.entrySet()) {
            CompoundTag haloEntryTag = new CompoundTag();
            if (haloEntry.getValue().hexColor() != null) {
                haloEntryTag.putString("HexColor", haloEntry.getValue().hexColor());
            }
            storedHaloDataTag.put(haloEntry.getKey().toString(), haloEntryTag);
        }
        tag.put("StoredHaloData", storedHaloDataTag);

        CompoundTag storedDeveloperGlowDataTag = new CompoundTag();
        for (Map.Entry<UUID, DeveloperGlow> developerGlowEntry : this.storedDeveloperGlowData.entrySet()) {
            CompoundTag developerGlowTag = new CompoundTag();
            if (developerGlowEntry.getValue().hexColor() != null) {
                developerGlowTag.putString("HexColor", developerGlowEntry.getValue().hexColor());
            }
            storedDeveloperGlowDataTag.put(developerGlowEntry.getKey().toString(), developerGlowTag);
        }
        tag.put("StoredDeveloperGlowData", storedDeveloperGlowDataTag);

        return tag;
    }

    /**
     * Loads perk data from the world from a {@link CompoundTag} representing the data in "perks.dat".
     *
     * @param tag The {@link CompoundTag}.
     * @return The {@link PerkSavedData} created from the world data.
     */
    public static PerkSavedData load(CompoundTag tag, HolderLookup.Provider lookupProvider) {
        PerkSavedData data = PerkSavedData.create();
        for (String key : tag.getAllKeys()) {
            if (key.equals("StoredSkinData")) {
                CompoundTag storedSkinDataTag = tag.getCompound(key);
                for (String storedSkinDataKey : storedSkinDataTag.getAllKeys()) {
                    CompoundTag moaDataEntryTag = storedSkinDataTag.getCompound(storedSkinDataKey);
                    UUID playerUUID = UUID.fromString(storedSkinDataKey);
                    UUID moaUUID = null;
                    String moaSkinId = null;
                    if (moaDataEntryTag.contains("MoaUUID")) {
                        moaUUID = moaDataEntryTag.getUUID("MoaUUID");
                    }
                    if (moaDataEntryTag.contains("MoaSkin")) {
                        moaSkinId = moaDataEntryTag.getString("MoaSkin");
                    }
                    MoaSkins.MoaSkin moaSkin = MoaSkins.getMoaSkins().get(moaSkinId);
                    data.storedSkinData.put(playerUUID, new MoaData(moaUUID, moaSkin));
                }
            }
            if (key.equals("StoredHaloData")) {
                CompoundTag storedHaloDataTag = tag.getCompound(key);
                for (String storedHaloDataKey : storedHaloDataTag.getAllKeys()) {
                    CompoundTag haloEntryTag = storedHaloDataTag.getCompound(storedHaloDataKey);
                    UUID playerUUID = UUID.fromString(storedHaloDataKey);
                    String hexColor = null;
                    if (haloEntryTag.contains("HexColor")) {
                        hexColor = haloEntryTag.getString("HexColor");
                    }
                    data.storedHaloData.put(playerUUID, new Halo(hexColor));
                }
            }
            if (key.equals("StoredDeveloperGlowData")) {
                CompoundTag storedDeveloperGlowDataTag = tag.getCompound(key);
                for (String storedDeveloperGlowDataKey : storedDeveloperGlowDataTag.getAllKeys()) {
                    CompoundTag developerGlowEntryTag = storedDeveloperGlowDataTag.getCompound(storedDeveloperGlowDataKey);
                    UUID playerUUID = UUID.fromString(storedDeveloperGlowDataKey);
                    String hexColor = null;
                    if (developerGlowEntryTag.contains("HexColor")) {
                        hexColor = developerGlowEntryTag.getString("HexColor");
                    }
                    data.storedDeveloperGlowData.put(playerUUID, new DeveloperGlow(hexColor));
                }
            }
        }
        return data;
    }

    public static PerkSavedData create() {
        return new PerkSavedData();
    }

    /**
     * Loads or creates the "perks.dat" file.
     *
     * @param dataStorage The {@link DimensionDataStorage} of the world.
     * @return The {@link PerkSavedData} corresponding to the data file.
     */
    public static PerkSavedData compute(DimensionDataStorage dataStorage) {
        return dataStorage.computeIfAbsent(new SavedData.Factory<>(PerkSavedData::create, PerkSavedData::load, null), FILE_NAME);
    }

    /**
     * @return A {@link Map} of player {@link UUID}s and {@link MoaData} retrieved from "perks.dat".
     */
    Map<UUID, MoaData> getStoredSkinData() {
        return ImmutableMap.copyOf(this.storedSkinData);
    }

    /**
     * Modifies the {@link MoaData} stored in the world data.
     *
     * @param uuid    The {@link UUID} of the player that the {@link MoaData} belongs to.
     * @param moaData The {@link MoaData}.
     */
    void modifyStoredSkinData(UUID uuid, MoaData moaData) {
        this.storedSkinData.put(uuid, moaData);
        this.setDirty();
    }

    /**
     * Removes an entry for a player's {@link MoaData} from the world data.
     *
     * @param uuid The player's {@link UUID}.
     */
    void removeStoredSkinData(UUID uuid) {
        this.storedSkinData.remove(uuid);
        this.setDirty();
    }

    /**
     * @return A {@link Map} of player {@link UUID}s and {@link Halo} info retrieved from "perks.dat".
     */
    Map<UUID, Halo> getStoredHaloData() {
        return ImmutableMap.copyOf(this.storedHaloData);
    }

    /**
     * Modifies the {@link Halo} info stored in the world data.
     *
     * @param uuid The {@link UUID} of the player that the {@link Halo} belongs to.
     * @param halo The {@link Halo}.
     */
    void modifyStoredHaloData(UUID uuid, Halo halo) {
        this.storedHaloData.put(uuid, halo);
        this.setDirty();
    }

    /**
     * Removes an entry for a player's {@link Halo} from the world data.
     *
     * @param uuid The player's {@link UUID}.
     */
    void removeStoredHaloData(UUID uuid) {
        this.storedHaloData.remove(uuid);
        this.setDirty();
    }

    /**
     * @return A {@link Map} of player {@link UUID}s and {@link DeveloperGlow} info retrieved from "perks.dat".
     */
    Map<UUID, DeveloperGlow> getStoredDeveloperGlowData() {
        return ImmutableMap.copyOf(this.storedDeveloperGlowData);
    }

    /**
     * Modifies the {@link DeveloperGlow} info stored in the world data.
     *
     * @param uuid          The {@link UUID} of the player that the {@link Halo} belongs to.
     * @param developerGlow The {@link DeveloperGlow}.
     */
    void modifyStoredDeveloperGlowData(UUID uuid, DeveloperGlow developerGlow) {
        this.storedDeveloperGlowData.put(uuid, developerGlow);
        this.setDirty();
    }

    /**
     * Removes an entry for a player's {@link DeveloperGlow} from the world data.
     *
     * @param uuid The player's {@link UUID}.
     */
    void removeStoredDeveloperGlowData(UUID uuid) {
        this.storedDeveloperGlowData.remove(uuid);
        this.setDirty();
    }
}

package com.aetherteam.aether.perk.data;

import com.aetherteam.aether.Aether;
import com.aetherteam.aether.network.packet.clientbound.ClientDeveloperGlowPacket;
import com.aetherteam.aether.network.packet.clientbound.ClientHaloPacket;
import com.aetherteam.aether.network.packet.clientbound.ClientMoaSkinPacket;
import com.aetherteam.aether.perk.PerkUtil;
import com.aetherteam.aether.perk.types.DeveloperGlow;
import com.aetherteam.aether.perk.types.Halo;
import com.aetherteam.aether.perk.types.MoaData;
import com.aetherteam.nitrogen.api.users.User;
import com.aetherteam.nitrogen.api.users.UserData;
import com.google.common.collect.ImmutableMap;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.neoforged.neoforge.network.PacketDistributor;
import org.apache.logging.log4j.util.TriConsumer;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.function.BiConsumer;
import java.util.function.BiFunction;
import java.util.function.Function;
import java.util.function.Predicate;

public class ServerPerkData<T> {
    /**
     * {@link ServerPerkData} instance for handling the {@link MoaData} perk type.<br>
     * This constructs the class with functions that are specific to calling and handling {@link MoaData} perk-related data.
     */
    public static final ServerPerkData<MoaData> MOA_SKIN_INSTANCE = new ServerPerkData<>(
            (data) -> (server) -> data.getSavedData(server).getStoredSkinData(),
            (data) -> (server, uuid, perk) -> data.getSavedData(server).modifyStoredSkinData(uuid, perk),
            (data) -> (server, uuid) -> data.getSavedData(server).removeStoredSkinData(uuid),
            (data) -> ClientMoaSkinPacket.Apply::new,
            (data) -> ClientMoaSkinPacket.Remove::new,
            (data) -> ClientMoaSkinPacket.Sync::new,
            (data) -> perk -> perk.moaSkin().getUserPredicate()
    );
    /**
     * {@link ServerPerkData} instance for handling the {@link Halo} perk type.<br>
     * This constructs the class with functions that are specific to calling and handling {@link Halo} perk-related data.
     */
    public static final ServerPerkData<Halo> HALO_INSTANCE = new ServerPerkData<>(
            (data) -> (server) -> data.getSavedData(server).getStoredHaloData(),
            (data) -> (server, uuid, perk) -> data.getSavedData(server).modifyStoredHaloData(uuid, perk),
            (data) -> (server, uuid) -> data.getSavedData(server).removeStoredHaloData(uuid),
            (data) -> ClientHaloPacket.Apply::new,
            (data) -> ClientHaloPacket.Remove::new,
            (data) -> ClientHaloPacket.Sync::new,
            (data) -> perk -> PerkUtil.hasHalo()
    );
    /**
     * {@link ServerPerkData} instance for handling the {@link DeveloperGlow} perk type.<br>
     * This constructs the class with functions that are specific to calling and handling {@link DeveloperGlow} perk-related data.
     */
    public static final ServerPerkData<DeveloperGlow> DEVELOPER_GLOW_INSTANCE = new ServerPerkData<>(
            (data) -> (server) -> data.getSavedData(server).getStoredDeveloperGlowData(),
            (data) -> (server, uuid, perk) -> data.getSavedData(server).modifyStoredDeveloperGlowData(uuid, perk),
            (data) -> (server, uuid) -> data.getSavedData(server).removeStoredDeveloperGlowData(uuid),
            (data) -> ClientDeveloperGlowPacket.Apply::new,
            (data) -> ClientDeveloperGlowPacket.Remove::new,
            (data) -> ClientDeveloperGlowPacket.Sync::new,
            (data) -> perk -> PerkUtil.hasDeveloperGlow()
    );

    private final Function<MinecraftServer, Map<UUID, T>> savedMap;
    private final TriConsumer<MinecraftServer, UUID, T> modify;
    private final BiConsumer<MinecraftServer, UUID> remove;
    private final BiFunction<UUID, T, CustomPacketPayload> applyPacket;
    private final Function<UUID, CustomPacketPayload> removePacket;
    private final Function<Map<UUID, T>, CustomPacketPayload> syncPacket;
    private final Function<T, Predicate<User>> verificationPredicate;

    public ServerPerkData(Function<ServerPerkData<T>, Function<MinecraftServer, Map<UUID, T>>> savedMap,
                          Function<ServerPerkData<T>, TriConsumer<MinecraftServer, UUID, T>> modify,
                          Function<ServerPerkData<T>, BiConsumer<MinecraftServer, UUID>> remove,
                          Function<ServerPerkData<T>, BiFunction<UUID, T, CustomPacketPayload>> applyPacket,
                          Function<ServerPerkData<T>, Function<UUID, CustomPacketPayload>> removePacket,
                          Function<ServerPerkData<T>, Function<Map<UUID, T>, CustomPacketPayload>> syncPacket,
                          Function<ServerPerkData<T>, Function<T, Predicate<User>>> verificationPredicate) {
        this.savedMap = savedMap.apply(this);
        this.modify = modify.apply(this);
        this.remove = remove.apply(this);
        this.applyPacket = applyPacket.apply(this);
        this.removePacket = removePacket.apply(this);
        this.syncPacket = syncPacket.apply(this);
        this.verificationPredicate = verificationPredicate.apply(this);
    }

    /**
     * Syncs the data for a perk from the server to the client.
     *
     * @param player The {@link Player} to send the packet to.
     */
    public void syncFromServer(Player player) {
        if (player instanceof ServerPlayer serverPlayer) {
            PacketDistributor.sendToPlayer(serverPlayer, this.getSyncPacket(this.getServerPerkData(serverPlayer.getServer()))); // Send to client.
        }
    }

    /**
     * Applies a perk as long as the player's {@link User} class exists and matches the verification requirement from {@link ServerPerkData#getVerificationPredicate(Object)}.<br>
     * The perk is sent to all players' clients with a packet, and the data for it is stored to the server world.
     *
     * @param server The {@link MinecraftServer}
     * @param uuid   The player's {@link UUID}
     * @param perk   The perk data type.
     */
    public void applyPerkWithVerification(MinecraftServer server, UUID uuid, T perk) {
        Map<UUID, User> storedUsers = UserData.Server.getStoredUsers();
        if (storedUsers.containsKey(uuid)) { // Checks if User exists.
            User user = storedUsers.get(uuid);
            try {
                if (user != null && this.getVerificationPredicate(perk).test(user)) { // Checks verification requirement to have the perk that is trying to be applied.
                    PacketDistributor.sendToAllPlayers(this.getApplyPacket(uuid, perk)); // Send to clients.
                    this.modifySavedData(server, uuid, perk); // Save to world.
                }
            } catch (RuntimeException e) {
                Aether.LOGGER.info(e.getMessage());
            }
        }
    }

    /**
     * Removes a perk from a player. The removal is relayed and synced to all players' clients with a packet.
     *
     * @param server The {@link MinecraftServer}.
     * @param uuid   The {@link UUID} of the player.
     */
    public void removePerk(MinecraftServer server, UUID uuid) {
        PacketDistributor.sendToAllPlayers(this.getRemovePacket(uuid)); // Send to clients.
        this.removeSavedData(server, uuid); // Save to world.
    }

    /**
     * Gets the data for all {@link UUID}s that have a specific perk (handled by subclasses).<br>
     * Before returning the data, this method runs verification checks on the information it gathers from the world.
     *
     * @param server The {@link MinecraftServer}.
     * @return A {@link Map} of player {@link UUID}s and perk {@link Object} data types.
     */
    public Map<UUID, T> getServerPerkData(MinecraftServer server) {
        Map<UUID, User> storedUsers = UserData.Server.getStoredUsers(); // The Users tracked and stored to the server world.
        Map<UUID, T> verifiedPerkData = new HashMap<>(); // An empty map of UUIDs and perk objects.
        for (Map.Entry<UUID, T> serverPerkDataEntry : this.getSavedMap(server).entrySet()) { // Iterates through perk data that is stored by the server world.
            if (storedUsers.containsKey(serverPerkDataEntry.getKey())) { // Ensures the UUID from the perk data map also exists in the user map.
                User user = storedUsers.get(serverPerkDataEntry.getKey()); // Gets the User corresponding to the UUID.
                try {
                    if (user != null && this.getVerificationPredicate(serverPerkDataEntry.getValue()).test(user)) { // Double checks whether the User has access to the perk that is currently attached to its UUID.
                        verifiedPerkData.put(serverPerkDataEntry.getKey(), serverPerkDataEntry.getValue()); // Adds the UUID and perk to the map indicating that the entry pair is verified.
                    }
                } catch (RuntimeException e) {
                    Aether.LOGGER.info(e.getMessage());
                }
            }
        }
        return ImmutableMap.copyOf(verifiedPerkData);
    }

    /**
     * @param server The {@link MinecraftServer}.
     * @return The {@link PerkSavedData} for the "perks.dat" file of the world.
     */
    protected PerkSavedData getSavedData(MinecraftServer server) {
        return PerkSavedData.compute(server.overworld().getDataStorage());
    }

    /**
     * Calls a get method from {@link PerkSavedData}
     *
     * @param server The {@link MinecraftServer}.
     * @return A {@link Map} of {@link UUID}s and a perk data type.
     */
    protected Map<UUID, T> getSavedMap(MinecraftServer server) {
        return this.savedMap.apply(server);
    }

    /**
     * Calls a modify method from {@link PerkSavedData}
     *
     * @param server The {@link MinecraftServer}.
     * @param uuid   The player {@link UUID}.
     * @param perk   The perk data type.
     */
    protected void modifySavedData(MinecraftServer server, UUID uuid, T perk) {
        this.modify.accept(server, uuid, perk);
    }

    /**
     * Calls a remove method from {@link PerkSavedData}.
     *
     * @param server The {@link MinecraftServer}.
     * @param uuid   The player {@link UUID}.
     */
    protected void removeSavedData(MinecraftServer server, UUID uuid) {
        this.remove.accept(server, uuid);
    }

    /**
     * Sends an application packet.
     *
     * @param uuid The player {@link UUID}.
     * @param perk The perk data type.
     * @return The packet.
     */
    protected CustomPacketPayload getApplyPacket(UUID uuid, T perk) {
        return this.applyPacket.apply(uuid, perk);
    }

    /**
     * Sends a removal packet.
     *
     * @param uuid The player {@link UUID}.
     * @return The packet.
     */
    protected CustomPacketPayload getRemovePacket(UUID uuid) {
        return this.removePacket.apply(uuid);
    }

    /**
     * Sends a sync packet.
     *
     * @param serverPerkData A {@link Map} of {@link UUID}s and a perk data type.
     * @return The packet.
     */
    protected CustomPacketPayload getSyncPacket(Map<UUID, T> serverPerkData) {
        return this.syncPacket.apply(serverPerkData);
    }

    /**
     * Gets the verification requirement for this perk.
     *
     * @param perk The perk data type.
     * @return A {@link User} {@link Predicate} for the perk.
     */
    protected Predicate<User> getVerificationPredicate(T perk) {
        return this.verificationPredicate.apply(perk);
    }
}

package net.tslat.aoa3.content.block.blockentity;

import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.tslat.aoa3.common.registration.AoARegistries;
import net.tslat.aoa3.common.registration.block.AoABlockEntities;
import net.tslat.aoa3.util.RegistryUtil;
import org.jetbrains.annotations.Nullable;


public class BossAltarBlockEntity extends BlockEntity {
	private EntityType<?> entityType = null;
	private Entity cachedEntity = null;

	public BossAltarBlockEntity(BlockPos pos, BlockState blockState) {
		super(AoABlockEntities.BOSS_ALTAR.get(), pos, blockState);
	}

	@Nullable
	public EntityType<?> getCurrentEntity() {
		return this.entityType;
	}

	@Nullable
	public Entity getCachedEntity() {
		return this.cachedEntity;
	}

	@Nullable
	@Override
	public Packet<ClientGamePacketListener> getUpdatePacket() {
		return ClientboundBlockEntityDataPacket.create(this);
	}

	public void updateEntity(@Nullable EntityType<?> entityType) {
		this.entityType = entityType;

		if (this.level != null)
			this.level.sendBlockUpdated(getBlockPos(), getBlockState(), getBlockState(), Block.UPDATE_ALL);
	}

	@Override
	public CompoundTag getUpdateTag(HolderLookup.Provider registryLookup) {
		CompoundTag tag = super.getUpdateTag(registryLookup);

		tag.putString("entityType", this.entityType == null ? "" : RegistryUtil.getId(this.entityType).toString());

		return tag;
	}

	@Override
	protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registryLookup) {
		super.loadAdditional(tag, registryLookup);

		if (tag.contains("entityType")) {
			String entityTypeString = tag.getString("entityType");

			if (entityTypeString.isEmpty()) {
				this.entityType = null;
			}
			else {
				this.entityType = AoARegistries.ENTITIES.getEntry(ResourceLocation.read(entityTypeString).getOrThrow());
			}

			if (this.cachedEntity != null)
				this.cachedEntity.discard();

			this.cachedEntity = this.entityType == null || this.level == null ? null : this.entityType.create(this.level);
		}
	}
}

package io.redspace.ironsspellbooks.data;

import io.redspace.ironsspellbooks.capabilities.magic.PocketDimensionManager;
import io.redspace.ironsspellbooks.capabilities.magic.PortalManager;
import io.redspace.ironsspellbooks.capabilities.magic.SummonManager;
import io.redspace.ironsspellbooks.effect.guiding_bolt.GuidingBoltManager;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.DimensionDataStorage;
import org.jetbrains.annotations.NotNull;

public class IronsDataStorage extends SavedData {
    public static IronsDataStorage INSTANCE;

    public static void init(DimensionDataStorage dimensionDataStorage) {
        if (dimensionDataStorage != null) {
            IronsDataStorage.INSTANCE = dimensionDataStorage.computeIfAbsent(
                    new Factory<IronsDataStorage>(IronsDataStorage::new, IronsDataStorage::load),
                    "irons_spellbooks_data");
        }
    }

    @Override
    public @NotNull CompoundTag save(@NotNull CompoundTag pCompoundTag, HolderLookup.Provider pRegistries) {
        var tag = new CompoundTag();
        //TODO: make annotation for this?
        tag.put("GuidingBoltManager", GuidingBoltManager.INSTANCE.serializeNBT(pRegistries));
        tag.put("PortalManager", PortalManager.INSTANCE.serializeNBT(pRegistries));
        tag.put("PocketDimensionIdManager", PocketDimensionManager.INSTANCE.serializeNBT(pRegistries));
        tag.put("SummonManager", SummonManager.INSTANCE.serializeNBT(pRegistries));
        return tag;
    }

    public static IronsDataStorage load(CompoundTag tag, HolderLookup.Provider pRegistries) {
        //TODO: make annotation for this?
        if (tag.contains("GuidingBoltManager", Tag.TAG_COMPOUND)) {
            GuidingBoltManager.INSTANCE.deserializeNBT(pRegistries, tag.getCompound("GuidingBoltManager"));
        }
        if (tag.contains("PortalManager", Tag.TAG_COMPOUND)) {
            PortalManager.INSTANCE.deserializeNBT(pRegistries, tag.getCompound("PortalManager"));
        }
        if (tag.contains("PocketDimensionIdManager", Tag.TAG_COMPOUND)) {
            PocketDimensionManager.INSTANCE.deserializeNBT(pRegistries, tag.getCompound("PocketDimensionIdManager"));
        }
        if (tag.contains("SummonManager", Tag.TAG_COMPOUND)) {
            SummonManager.INSTANCE.deserializeNBT(pRegistries, tag.getCompound("SummonManager"));
        }

        return new IronsDataStorage();
    }

}

